package codeextract

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

var ignoredFallbackDirs = map[string]struct{}{
	".git":         {},
	".hg":          {},
	".svn":         {},
	"node_modules": {},
	".ultraplan":   {},
}

type resolver struct {
	workspaceRoot string
	reportDir     string
	sources       []Source
	// basenameCache is intentionally scoped to one extraction invocation so
	// fallback search never persists stale filesystem state.
	basenameCache map[string][]string
}

func newResolver(workspaceRoot, reportPath string, sources []Source) (*resolver, []Source, []Diagnostic) {
	r := &resolver{
		workspaceRoot: workspaceRoot,
		reportDir:     filepath.Dir(reportPath),
		basenameCache: map[string][]string{},
	}
	resolved := make([]Source, 0, len(sources))
	var diagnostics []Diagnostic
	for _, source := range sources {
		root, err := resolveSourceRoot(workspaceRoot, r.reportDir, source.Path)
		if err != nil {
			diagnostics = append(diagnostics, Diagnostic{ReportPath: reportPath, SourceName: source.Name, Path: source.Path, Reason: err.Error()})
			continue
		}
		source.Root = root
		resolved = append(resolved, source)
	}
	r.sources = resolved
	return r, resolved, diagnostics
}

func resolveSourceRoot(workspaceRoot, reportDir, raw string) (string, error) {
	candidates := []string{filepath.Join(workspaceRoot, filepath.FromSlash(raw)), filepath.Join(reportDir, filepath.FromSlash(raw))}
	for _, candidate := range candidates {
		contained, err := containedPath(workspaceRoot, candidate)
		if err != nil {
			continue
		}
		info, statErr := os.Stat(contained)
		if statErr == nil && info.IsDir() {
			return contained, nil
		}
	}
	return "", fmt.Errorf("source root not found or outside workspace")
}

func (r *resolver) resolve(citedPath string) (Source, string, *Diagnostic) {
	if strings.Contains(citedPath, "\x00") {
		return Source{}, "", &Diagnostic{Path: citedPath, Reason: "path contains NUL byte"}
	}
	if filepath.IsAbs(citedPath) {
		return Source{}, "", &Diagnostic{Path: citedPath, Reason: "absolute paths are not allowed"}
	}
	cleaned := filepath.Clean(filepath.FromSlash(citedPath))
	if cleaned == "." || strings.HasPrefix(cleaned, ".."+string(filepath.Separator)) || cleaned == ".." {
		return Source{}, "", &Diagnostic{Path: citedPath, Reason: "path escapes source root"}
	}
	for _, source := range r.sources {
		if path, ok := existingContainedFile(source.Root, cleaned); ok {
			return source, path, nil
		}
		parts := strings.Split(cleaned, string(filepath.Separator))
		if len(parts) > 1 && parts[0] == source.Name {
			stripped := filepath.Join(parts[1:]...)
			if path, ok := existingContainedFile(source.Root, stripped); ok {
				return source, path, nil
			}
		}
	}
	matches := r.basenameMatches(filepath.Base(cleaned))
	if len(matches) == 1 {
		for _, source := range r.sources {
			if inside(source.Root, matches[0]) {
				return source, matches[0], nil
			}
		}
	}
	if len(matches) > 1 {
		return Source{}, "", &Diagnostic{Path: citedPath, Reason: "ambiguous basename match"}
	}
	return Source{}, "", &Diagnostic{Path: citedPath, Reason: "file not found"}
}

func existingContainedFile(root, rel string) (string, bool) {
	path, err := containedPath(root, filepath.Join(root, rel))
	if err != nil {
		return "", false
	}
	info, err := os.Stat(path)
	if err != nil || info.IsDir() {
		return "", false
	}
	return path, true
}

func containedPath(root, candidate string) (string, error) {
	rootAbs, err := filepath.Abs(root)
	if err != nil {
		return "", err
	}
	candAbs, err := filepath.Abs(candidate)
	if err != nil {
		return "", err
	}
	rootEval, err := filepath.EvalSymlinks(rootAbs)
	if err != nil {
		rootEval = rootAbs
	}
	candEval, err := filepath.EvalSymlinks(candAbs)
	if err != nil {
		candEval = candAbs
	}
	if !inside(rootEval, candEval) {
		return "", fmt.Errorf("path escapes root")
	}
	return candAbs, nil
}

func inside(root, candidate string) bool {
	rel, err := filepath.Rel(root, candidate)
	if err != nil {
		return false
	}
	return rel == "." || (rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator)))
}

func (r *resolver) basenameMatches(base string) []string {
	if matches, ok := r.basenameCache[base]; ok {
		return matches
	}
	var matches []string
	for _, source := range r.sources {
		_ = filepath.WalkDir(source.Root, func(path string, entry os.DirEntry, err error) error {
			if err != nil {
				return nil
			}
			if entry.IsDir() {
				if _, ignored := ignoredFallbackDirs[entry.Name()]; ignored {
					return filepath.SkipDir
				}
				return nil
			}
			if entry.Name() == base && inside(source.Root, path) {
				matches = append(matches, path)
			}
			return nil
		})
	}
	sort.Strings(matches)
	r.basenameCache[base] = matches
	return matches
}

package codeextract

import (
	"fmt"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

var inlineCitationPattern = regexp.MustCompile("`([^`\\n]+:[0-9][0-9,\\-– ]*)`")

type parsedReference struct {
	citation string
	path     string
	lineSpec string
	lines    []int
}

func parseReport(content, reportPath string) ([]Source, []parsedReference, []Diagnostic) {
	refs, refDiagnostics := parseReferences(content, reportPath)
	sources, sourceDiagnostics := parseSources(content, reportPath)
	diagnostics := append(sourceDiagnostics, refDiagnostics...)
	return sources, refs, diagnostics
}

func parseReferences(content, reportPath string) ([]parsedReference, []Diagnostic) {
	matches := inlineCitationPattern.FindAllStringSubmatch(content, -1)
	refs := make([]parsedReference, 0, len(matches))
	var diagnostics []Diagnostic
	seen := map[string]struct{}{}
	for _, match := range matches {
		citation := match[1]
		if _, ok := seen[citation]; ok {
			continue
		}
		seen[citation] = struct{}{}
		path, spec, ok := strings.Cut(citation, ":")
		if !ok || strings.TrimSpace(path) == "" || strings.TrimSpace(spec) == "" {
			diagnostics = append(diagnostics, Diagnostic{ReportPath: reportPath, Citation: citation, Reason: "malformed citation"})
			continue
		}
		lines, normalized, err := parseLineSpec(spec)
		if err != nil {
			diagnostics = append(diagnostics, Diagnostic{ReportPath: reportPath, Citation: citation, Path: path, Reason: err.Error()})
			continue
		}
		refs = append(refs, parsedReference{
			citation: citation,
			path:     strings.TrimSpace(path),
			lineSpec: normalized,
			lines:    lines,
		})
	}
	sort.SliceStable(refs, func(i, j int) bool { return refs[i].citation < refs[j].citation })
	return refs, diagnostics
}

func parseLineSpec(raw string) ([]int, string, error) {
	spec := strings.ReplaceAll(strings.TrimSpace(raw), "–", "-")
	if strings.Contains(spec, "-") {
		parts := strings.Split(spec, "-")
		if len(parts) != 2 {
			return nil, "", fmt.Errorf("malformed line range %q", raw)
		}
		start, err := parsePositiveLine(parts[0])
		if err != nil {
			return nil, "", err
		}
		end, err := parsePositiveLine(parts[1])
		if err != nil {
			return nil, "", err
		}
		if end < start {
			return nil, "", fmt.Errorf("line range %q ends before it starts", raw)
		}
		lines := make([]int, 0, end-start+1)
		for i := start; i <= end; i++ {
			lines = append(lines, i)
		}
		return lines, fmt.Sprintf("%d-%d", start, end), nil
	}
	parts := strings.Split(spec, ",")
	lines := make([]int, 0, len(parts))
	normalized := make([]string, 0, len(parts))
	for _, part := range parts {
		line, err := parsePositiveLine(part)
		if err != nil {
			return nil, "", err
		}
		lines = append(lines, line)
		normalized = append(normalized, strconv.Itoa(line))
	}
	return lines, strings.Join(normalized, ","), nil
}

func parsePositiveLine(raw string) (int, error) {
	n, err := strconv.Atoi(strings.TrimSpace(raw))
	if err != nil || n < 1 {
		return 0, fmt.Errorf("line numbers must be positive integers")
	}
	return n, nil
}

func parseSources(content, reportPath string) ([]Source, []Diagnostic) {
	var sources []Source
	var diagnostics []Diagnostic
	seen := map[string]struct{}{}
	for _, line := range strings.Split(content, "\n") {
		trimmed := strings.TrimSpace(line)
		if !strings.HasPrefix(trimmed, "|") || !strings.HasSuffix(trimmed, "|") {
			continue
		}
		cells := splitMarkdownRow(trimmed)
		if len(cells) < 3 {
			continue
		}
		index, err := strconv.Atoi(strings.TrimSpace(cells[0]))
		if err != nil {
			continue
		}
		name := strings.TrimSpace(cells[1])
		path := strings.Trim(strings.TrimSpace(cells[2]), "`")
		if name == "" || path == "" {
			diagnostics = append(diagnostics, Diagnostic{ReportPath: reportPath, Reason: "malformed source row"})
			continue
		}
		if _, ok := seen[name]; ok {
			diagnostics = append(diagnostics, Diagnostic{ReportPath: reportPath, SourceName: name, Reason: "duplicate source row"})
			continue
		}
		seen[name] = struct{}{}
		sources = append(sources, Source{Index: index, Name: name, Path: path})
	}
	sort.SliceStable(sources, func(i, j int) bool {
		if sources[i].Index == sources[j].Index {
			return sources[i].Name < sources[j].Name
		}
		return sources[i].Index < sources[j].Index
	})
	return sources, diagnostics
}

func splitMarkdownRow(row string) []string {
	trimmed := strings.Trim(row, "|")
	parts := strings.Split(trimmed, "|")
	for i := range parts {
		parts[i] = strings.TrimSpace(parts[i])
	}
	return parts
}

